-- Classic -> LoY missing NPC backfill
-- Source: ProjectEQ world DB archive (db.eqemu.dev) peq-1788566415.zip
-- Generated: 2026-09-11. Idempotent (INSERT IGNORE).
SET NAMES utf8mb4;
START TRANSACTION;
-- npc_types: 130 rows
-- npc_faction: 1 rows
-- loottable: 2 rows
-- loottable_entries: 5 rows
-- lootdrop: 5 rows
-- lootdrop_entries: 51 rows
-- spawngroup: 127 rows (ids remapped to 60005051+)
-- spawnentry: 175 rows
-- spawn2: 268 rows (ids remapped to 45000363+)
COMMIT;

-- Normalize inserted spawn version to the version this DB actually runs.
-- PEQ models some revamps (lavastorm/paw/nektulos) as a separate zone version (v1);
-- this DB has no such zone row and stores the revamp content at v0. Left at PEQ's v1
-- these spawns would be dormant. Scope = our inserted spawngroups only.
START TRANSACTION;
UPDATE spawn2 SET version = 0
WHERE spawngroupID BETWEEN 60005051 AND 60005177
  AND NOT EXISTS (SELECT 1 FROM zone z WHERE z.short_name = spawn2.zone AND z.version = spawn2.version);
COMMIT;